function shortestRoute(){const q=[[[0,4],[]]],seen=new Set(['0,4']);while(q.length){const [p,r]=q.shift();if(p[0]===4&&p[1]===0)return r;for(const d of Object.keys(delta)){const n=[p[0]+delta[d][0],p[1]+delta[d][1]],k=n.join();if(n.some(v=>v<0||v>4)||levels[level].walls.some(w=>w.join()===k)||seen.has(k))continue;seen.add(k);q.push([n,[...r,d]])}}return []}
